<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';$admin=require_admin($pdo);header('Cache-Control: private, no-store');header('Vary: Cookie');$success='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{$op=(string)($_POST['op']??'');if($op==='rebuild'){$n=search_rebuild_public_entities($pdo,2000);$success="Discovery index rebuilt with $n report entity mentions.";}elseif($op==='rename'){search_admin_entity_rename($pdo,$admin,(string)$_POST['id'],(string)$_POST['name'],(string)($_POST['description']??''));$success='Entity updated.';}elseif($op==='alias'){search_admin_entity_alias($pdo,$admin,(string)$_POST['id'],(string)$_POST['alias']);$success='Alias added.';}elseif($op==='merge'){search_admin_entity_merge($pdo,$admin,(string)$_POST['from_id'],(string)$_POST['into_id']);$success='Entities merged.';}}catch(Throwable $e){$error=$e->getMessage();}}
$q=$pdo->query("SELECT de.*,COUNT(dem.object_public_id) mention_count,(SELECT GROUP_CONCAT(alias_name ORDER BY alias_name SEPARATOR ', ') FROM discovery_entity_aliases da WHERE da.entity_id=de.id) aliases FROM discovery_entities de LEFT JOIN discovery_entity_mentions dem ON dem.entity_id=de.id GROUP BY de.id ORDER BY FIELD(de.status,'active','merged','hidden'),mention_count DESC,de.canonical_name LIMIT 300");$entities=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Discovery Entities · Annotated Admin</title><meta name="robots" content="noindex,nofollow"><link rel="stylesheet" href="/assets/css/app.css"></head><body><?=admin_ui_sidebar('discovery_entities')?>
<header class="topbar"><a class="brand" href="/admin/">Annotated Admin</a><nav><a href="/admin/moderation.php">Moderation</a><a href="/admin/source-monitor.php">Sources</a></nav></header><main class="panel moderationConsole"><div class="pageTitle"><span class="eyebrow">PHASE 10</span><h1>Discovery entities</h1><p>Correct the public discovery layer without mutating Research-project entities or report snapshots.</p></div><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?>
<form method="post" class="inlineActions"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="rebuild"><button>Rebuild from public reports</button></form>
<h2>Merge duplicates</h2><form method="post" class="card searchAdminMerge"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="merge"><label>Merge entity ID<input name="from_id" required></label><label>Into entity ID<input name="into_id" required></label><button>Merge</button></form>
<h2>Entity index</h2><?php foreach($entities as $e):?><article class="card trustCase"><div class="caseHeader"><div><span class="badge"><?=h($e['entity_type'])?></span><span class="badge"><?=h($e['status'])?></span><strong><?=h($e['canonical_name'])?></strong></div><span class="meta"><?=h((string)$e['mention_count'])?> mentions · <?=h($e['public_id'])?></span></div><?php if($e['description']):?><p><?=h(mb_substr((string)$e['description'],0,500))?></p><?php endif?><?php if($e['aliases']):?><p class="meta">Aliases: <?=h((string)$e['aliases'])?></p><?php endif?>
<?php if($e['status']==='active'):?><div class="adminEntityForms"><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="rename"><input type="hidden" name="id" value="<?=h($e['public_id'])?>"><label>Name<input name="name" value="<?=h($e['canonical_name'])?>" required></label><label>Description<textarea name="description" rows="2"><?=h((string)$e['description'])?></textarea></label><button class="button secondary">Save correction</button></form><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="alias"><input type="hidden" name="id" value="<?=h($e['public_id'])?>"><label>Add alias<input name="alias" required></label><button class="button secondary">Add alias</button></form></div><?php endif?></article><?php endforeach?></main></body></html>